const input = $input.first()?.json ?? {};
const mode = $execution.mode;
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
let businessDate;
let source;
if (mode === 'manual') {
  businessDate = String(input.business_date ?? '').trim();
  if (!datePattern.test(businessDate)) throw new Error('MANUAL_BUSINESS_DATE_REQUIRED: provide explicit YYYY-MM-DD input');
  const [year, month, day] = businessDate.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));
  if (parsed.getUTCFullYear() !== year || parsed.getUTCMonth() !== month - 1 || parsed.getUTCDate() !== day) throw new Error('MANUAL_BUSINESS_DATE_REQUIRED: provide explicit YYYY-MM-DD input');
  source = 'MANUAL_EXPLICIT';
} else {
  if (!input.timestamp) throw new Error('SCHEDULED_TIMESTAMP_REQUIRED');
  const scheduledAt = new Date(input.timestamp);
  if (Number.isNaN(scheduledAt.getTime())) throw new Error('SCHEDULED_TIMESTAMP_INVALID');
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(scheduledAt).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  const target = new Date(Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day)));
  target.setUTCDate(target.getUTCDate() - 1);
  businessDate = target.toISOString().slice(0, 10);
  source = 'SCHEDULED_PREVIOUS_MSK_DAY';
}
return [{json:{business_date:businessDate,delivery_context_locked:true,delivery_context_source:source}}];

const brief = $input.first().json;
const lockedDate = $('Lock Delivery Business Date').first().json.business_date;
const canonicalOffers = ['УФ 001Б','УФ 002Б','УФ 003Б','УФ 004Б','УФ 005Б'];
if (!brief || typeof brief.business_date !== 'string' || !Array.isArray(brief.offers) || !brief.data_quality || typeof brief.data_quality !== 'object') throw new Error('BRIEF_BUILD_FAILED');
if (brief.business_date !== lockedDate) throw new Error(`DELIVERY_DATE_CONTEXT_MISMATCH: expected ${lockedDate}, received ${brief.business_date}`);
const actualOffers = brief.offers.map((item) => item.offer_id).sort();
if (actualOffers.length !== canonicalOffers.length || actualOffers.some((offer, index) => offer !== canonicalOffers.slice().sort()[index])) throw new Error('BRIEF_BUILD_FAILED: canonical_offer_contract');
return [{json:{business_date:lockedDate,delivery_context_locked:true,report_version:'v0.1',stale_data_warning:Boolean(brief.data_quality.warnings?.length),data_quality:brief.data_quality,preflight_status:'SUCCESS'}}];

const item = $input.first().json;
const key = `daily-brief:${item.report_version}:production:email:${item.business_date}`;
const ledger = $getWorkflowStaticData('global');
if (ledger[key]) return [];
return [{json:{...item,channel:'email',delivery_key:key,delivery_status:'PENDING'}}];

const context = $('Check Email Delivery').item.json;
const result = $input.first().json;
if (result?.error) return [{json:{channel:'email',status:'EMAIL_FAILED',delivery_key:context.delivery_key}}];
const ledger = $getWorkflowStaticData('global');
ledger[context.delivery_key] = {status:'SUCCESS',business_date:context.business_date,report_version:context.report_version,marked_at:new Date().toISOString()};
return [{json:{channel:'email',status:'SUCCESS',delivery_key:context.delivery_key}}];

const item = $input.first().json;
const key = `daily-brief:${item.report_version}:production:telegram:${item.business_date}`;
const ledger = $getWorkflowStaticData('global');
if (ledger[key]) return [];
return [{json:{...item,channel:'telegram',delivery_key:key,delivery_status:'PENDING'}}];

const context = $('Check Telegram Delivery').item.json;
const result = $input.first().json;
if (result?.error) return [{json:{channel:'telegram',status:'TELEGRAM_FAILED',delivery_key:context.delivery_key}}];
const ledger = $getWorkflowStaticData('global');
ledger[context.delivery_key] = {status:'SUCCESS',business_date:context.business_date,report_version:context.report_version,marked_at:new Date().toISOString()};
return [{json:{channel:'telegram',status:'SUCCESS',delivery_key:context.delivery_key}}];
